-- MP-0030: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='government' and type='bloc') then raise exception 'MP-0030: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0030: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'MP-0030: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('mohd-hasnizan-harun','zulkafperi-hanapi','william-leong-jee-keen') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0030: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('hulu selangor','tanjong karang','selayang') and slug not in ('mohd-hasnizan-harun','zulkafperi-hanapi','william-leong-jee-keen')) then raise exception 'MP-0030: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0030:%' and (m.source_type <> 'editorial' or e.slug not in ('mohd-hasnizan-harun','zulkafperi-hanapi','william-leong-jee-keen') or m.import_key not like 'MP-0030:' || e.slug || ':%')) then raise exception 'MP-0030: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'mohd-hasnizan-harun','Mohd Hasnizan Harun','opposition','Member of the Dewan Rakyat','Hulu Selangor','Selangor','Mohd Hasnizan Harun represents Hulu Selangor, Selangor, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4133','/portraits/mohd-hasnizan-harun.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P094.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4133"}, {"label": "PAS · parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'zulkafperi-hanapi','Zulkafperi Hanapi','government','Member of the Dewan Rakyat','Tanjong Karang','Selangor','Zulkafperi Hanapi represents Tanjong Karang, Selangor, in the Dewan Rakyat. An independent MP supporting the government under the reported confidence-and-supply agreement.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4134','/portraits/zulkafperi-hanapi.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P095.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4134"}, {"label": "Independent MP · confidence-and-supply agreement, 29 October 2026", "url": "https://bernama.com/bm/am/news.php?id=2627381"}]'::jsonb from public.entities parent where parent.slug='government' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'william-leong-jee-keen','William Leong Jee Keen','government','Member of the Dewan Rakyat','Selayang','Selangor','William Leong Jee Keen represents Selayang, Selangor, in the Dewan Rakyat. A PKR member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4136','/portraits/william-leong-jee-keen.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P097.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4136"}, {"label": "PKR · current representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('mohd-hasnizan-harun','zulkafperi-hanapi','william-leong-jee-keen') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0030: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0030:zulkafperi-hanapi:budget-2027-csa','Support Supply Bill 2027 under the confidence-and-supply agreement','Governance',null,null,null,'2026-10-29','https://bernama.com/bm/am/news.php?id=2627381',null,null,'Signed the agreement to support the 2027 Supply Bill.','Signing is confirmed; subsequent voting and budget passage were not verified.','2026-11-09','editorial',false from public.entities e where e.slug='zulkafperi-hanapi' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0030:william-leong-jee-keen:rawang-roadside-drain','Fund drainage improvements along Jalan Rawang FT01','Infrastructure','in_progress',null,null,null,null,'2025-05-09','https://mediaselangor.com/ms/2025/05/263899','The Rawang representative reported a roadside drain funded through William Leong’s parliamentary allocation to reduce standing water.','The May 2025 report documents implementation by the constituency and road authorities. The separate nearly-80% figure covers nine road-safety locations and is not a completion metric for this drain.','2026-11-09','editorial',false from public.entities e where e.slug='william-leong-jee-keen' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

